<?php

/* @autogenerated */
declare(strict_types=1);

use PHPUnit\Framework\TestCase;
use Civi\Lughauth\Shared\Exception\ConstraintException;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use Civi\Lughauth\Features\Document\SnippetAsset\Domain\ValueObject\SnippetAssetContentVO;

final class SnippetAssetContentVOUnitTest extends TestCase
{
    public function test_asignation_keep_value(): void
    {
        $value = 'store://bin';
        $ref = SnippetAssetContentVO::from($value);
        $this->assertEquals('bin', $ref->value());
        $other = SnippetAssetContentVO::tryFrom($ref, new ConstraintFailList());
        $this->assertSame($other, $ref);
        $more = SnippetAssetContentVO::from($ref);
        $this->assertSame($more, $ref);
    }
    public function test_asignation_invalid_type(): void
    {
        $errors = new ConstraintFailList();
        $other = SnippetAssetContentVO::tryFrom(1, $errors);
        $this->assertNull($other);
        $this->assertTrue($errors->hasErrors());
    }
    public function test_optimist_asignation_invalid_type(): void
    {
        $this->expectException(ConstraintException::class);
        $method = new ReflectionMethod(SnippetAssetContentVO::class, 'fromUnsafe');
        $method->invoke(null, [11, "bad"]);
    }
    public function test_equals(): void
    {
        $one = SnippetAssetContentVO::from('store://bin');
        $same = SnippetAssetContentVO::from('store://bin');
        $other = SnippetAssetContentVO::from('store://obin');
        $withEmpty = $one->equals(null);
        $withSame = $one->equals($same);
        $withOther = $one->equals($other);

        $this->assertFalse($withEmpty);
        $this->assertTrue($withSame);
        $this->assertFalse($withOther);
    }
    public function test_cypher_builders(): void
    {
        $errors = new ConstraintFailList();
        $temp = SnippetAssetContentVO::fromTemporal('tempus');
        $this->assertEquals('tempus', $temp->value());
        $temp = SnippetAssetContentVO::tryFromTemporal('tempus', $errors);
        $this->assertEquals('tempus', $temp->value());
        $this->assertTrue($errors->isEmpty());
        $external = SnippetAssetContentVO::fromStored('http://www.php.net/');
        $this->assertEquals('http://www.php.net/', $external->value());
        $external = SnippetAssetContentVO::tryFromStored('http://www.php.net/', $errors);
        $this->assertEquals('http://www.php.net/', $external->value());
        $this->assertTrue($errors->isEmpty());
        $internal = SnippetAssetContentVO::fromStored('none');
        $this->assertEquals('none', $internal->value());
        $external = SnippetAssetContentVO::tryFromStored('none', $errors);
        $this->assertEquals('none', $internal->value());
        $this->assertTrue($errors->isEmpty());
    }
    public function test_invalid_file_schmea(): void
    {
        $this->expectException(\InvalidArgumentException::class);
        SnippetAssetContentVO::from('none');
    }
}
